  .corner-br { bottom: 8px; right: 8px; }

  .content {
    font-size: 14px;
    line-height: 1.9;
    color: #222;
    text-align: justify;
  }
  .indent {
    text-indent: 2em;
    margin: 4px 0 14px 0;
  }
  h2.section {
    color: #c81e1e;
    font-size: 19px;
    font-weight: bold;
    margin: 16px 0 6px 0;
  }
  .red {
    color: #c81e1e;
    font-weight: bold;
  }
  .deco {
    position: absolute;
    width: 26px;
    height: 26px;
    border-radius: 50%;
    background: repeating-conic-gradient(#c81e1e 0deg 90deg, #fff 90deg 180deg);
  }
  .deco-tl { top: -13px; left: -13px; }
  .deco-tr { top: -13px; right: -13px; }
  .deco-bl { bottom: -13px; left: -13px; }
  .deco-br { bottom: -13px; right: -13px; }
